const payload = {
  id: 'evt_demo_invoice_failed_001',
  type: 'invoice.payment_failed',
  livemode: false,
  created: 1780502500,
  data: {
    object: {
      id: 'in_acme_failed_001',
      customer: 'cus_acme_ai',
      subscription: 'sub_acme_scale',
      amount_due: 120000,
      currency: 'usd',
      attempt_count: 1,
      last_payment_error: {
        code: 'card_declined',
        message: 'The card was declined.'
      },
      metadata: {
        account_domain: 'acme.ai',
        crm_company_id: 'crm_acme_ai',
        usage_density: '87'
      }
    }
  }
};

return [{ json: payload }];

const churn = $json.churnDefuser ?? {};
const classification = churn.classification ?? {};
const crmTask = churn.crmTask ?? null;
const notification = churn.notification ?? null;
const dlq = churn.deadLetterQueue ?? null;

return [{
  json: {
    accountName: churn.account?.name ?? 'Unknown account',
    riskLevel: classification.riskLevel ?? 'unknown',
    requiresHumanTask: classification.shouldCreateHumanTask ?? false,
    shouldNotifyOps: classification.shouldNotifyOps ?? false,
    recommendedAction: classification.recommendedAction ?? 'Review the ingest response.',
    suggestedNextStep: churn.response?.suggestedNextStep ?? 'Inspect the dashboard response.',
    crmTask,
    notification,
    deadLetterQueue: dlq,
    rawResponse: $json
  }
}];

return [{
  json: {
    severity: $json.riskLevel,
    accountName: $json.accountName,
    recommendedAction: $json.recommendedAction,
    suggestedNextStep: $json.suggestedNextStep,
    crmTask: $json.crmTask,
    notification: $json.notification,
    message: 'High or critical path: route to the Ops Action Center, stage mock CRM follow-up, and keep the outbox payload visible.'
  }
}];

return [{
  json: {
    severity: $json.riskLevel,
    accountName: $json.accountName,
    recommendedAction: $json.recommendedAction,
    suggestedNextStep: $json.suggestedNextStep,
    notification: $json.notification,
    message: 'Automation-first path: keep dunning and monitoring active until another payment attempt fails.'
  }
}];

return [{
  json: {
    message: 'Deterministic downstream failure was requested. Review the queued dead-letter item and use the retry worker later.',
    deadLetterQueue: $json.deadLetterQueue
  }
}];

return [{
  json: {
    message: 'No DLQ item was created. Notification outbox and mock CRM task data are still available in the response.'
  }
}];
